IF ISJSON(@Payload) <> 1
    OR JSON_VALUE(@Payload, '$.schemaVersion') IS NULL
    OR JSON_VALUE(@Payload, '$.schemaVersion') <> '1.0-source-invoice-load'
    THROW 51412, 'Generate the reviewed source payload before loading.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

SELECT * INTO #SourceInvoice
FROM OPENJSON(@Payload, '$.invoices') WITH
(
    InvoiceID nvarchar(128), InvoiceNumber nvarchar(128), InvoiceDate date,
    VendorID nvarchar(128), VendorName nvarchar(300), InvoiceCurrency char(3),
    InvoiceTotal decimal(19,4), PONumber nvarchar(128), CountryRegion nvarchar(100),
    SourceSystem nvarchar(64), NuvoloWorkOrderNo nvarchar(128), HasLineItems bit, RunID nvarchar(128)
);
SELECT * INTO #SourcePackage
FROM OPENJSON(@Payload, '$.packages') WITH
(
    PackageId nvarchar(128), SchemaVersion varchar(16), RunId nvarchar(128),
    InvoiceId nvarchar(128), InvoiceNumber nvarchar(128), InvoiceDate date,
    VendorId nvarchar(128), VendorName nvarchar(300), Currency char(3),
    InvoiceTotal decimal(19,4), PoNumber nvarchar(128), CountryRegion nvarchar(100),
    SourceSystem nvarchar(64), BusinessUnit nvarchar(100), ProjectStatus nvarchar(100),
    ProjectType nvarchar(100), BundlingInScope bit, MissingPo bit, MissingProject bit,
    MissingSite bit, SourcePackageName nvarchar(1024), SourceSha256 char(64),
    CreatedAtUtc datetimeoffset(3), PackageStatus varchar(16), SourceMetadataJson nvarchar(max) AS JSON
);
SELECT * INTO #SourceLine
FROM OPENJSON(@Payload, '$.lines') WITH
(
    PackageId nvarchar(128), InvoiceLineId nvarchar(256), InvoiceID nvarchar(128),
    LineNumber int, Description nvarchar(2000), PartNumber nvarchar(256),
    Quantity decimal(19,4), UnitCost decimal(19,4), LineAmount decimal(19,4),
    PoLineNumber int, PoDescription nvarchar(2000), PoTaskCode nvarchar(128),
    AfeProjectId nvarchar(128), SiteId nvarchar(128), SourceLineJson nvarchar(max) AS JSON
);

IF (SELECT COUNT_BIG(*) FROM #SourceInvoice) <> 10
    OR (SELECT COUNT_BIG(*) FROM #SourcePackage) <> 10
    OR (SELECT COUNT_BIG(*) FROM #SourceLine) <> 30
    OR EXISTS (SELECT InvoiceID FROM #SourceInvoice GROUP BY InvoiceID HAVING COUNT(*) <> 1)
    OR EXISTS (SELECT PackageId FROM #SourcePackage GROUP BY PackageId HAVING COUNT(*) <> 1)
    OR EXISTS (SELECT PackageId, InvoiceLineId FROM #SourceLine
        GROUP BY PackageId, InvoiceLineId HAVING COUNT(*) <> 1)
    THROW 51413, 'Expected 10 distinct invoices/packages and 30 source lines. Nothing was loaded.', 1;

IF EXISTS (
    SELECT 1 FROM #SourceLine AS line
    LEFT JOIN #SourcePackage AS package ON package.PackageId = line.PackageId
    LEFT JOIN #SourceInvoice AS invoice ON invoice.InvoiceID = line.InvoiceID
    WHERE package.PackageId IS NULL OR invoice.InvoiceID IS NULL
       OR package.InvoiceId <> line.InvoiceID
)
    THROW 51414, 'Source invoice/package/line links do not reconcile.', 1;

DECLARE @LockCount bigint;
    SELECT * INTO #TaskMasterBeforeLoad FROM ref.TaskMaster WITH (TABLOCK, HOLDLOCK);
    SELECT @LockCount = COUNT_BIG(*) FROM prep.Invoice WITH (TABLOCKX, HOLDLOCK);
    SELECT @LockCount = COUNT_BIG(*) FROM prep.InvoicePackage WITH (TABLOCKX, HOLDLOCK);
    SELECT @LockCount = COUNT_BIG(*) FROM prep.InvoiceLine WITH (TABLOCKX, HOLDLOCK);

    IF EXISTS (
        SELECT 1 FROM sys.triggers
        WHERE parent_id IN (OBJECT_ID(N'prep.Invoice'), OBJECT_ID(N'prep.InvoicePackage'),
            OBJECT_ID(N'prep.InvoiceLine')) AND is_disabled = 0
    )
        THROW 51420, 'Enabled invoice-table triggers require review before loading. Nothing was loaded.', 1;

    IF EXISTS (
        SELECT InvoiceID, InvoiceNumber, InvoiceDate, VendorID, VendorName, InvoiceCurrency,
            InvoiceTotal, PONumber, CountryRegion, SourceSystem, NuvoloWorkOrderNo, HasLineItems, RunID
        FROM prep.Invoice WHERE InvoiceID IN (SELECT InvoiceID FROM #SourceInvoice)
        EXCEPT SELECT * FROM #SourceInvoice
    )
        THROW 51415, 'An existing invoice differs from source facts. No data was overwritten.', 1;
    IF EXISTS (
        SELECT PackageId, SchemaVersion, RunId, InvoiceId, InvoiceNumber, InvoiceDate,
            VendorId, VendorName, Currency, InvoiceTotal, PoNumber, CountryRegion, SourceSystem,
            BusinessUnit, ProjectStatus, ProjectType, BundlingInScope, MissingPo, MissingProject,
            MissingSite, SourcePackageName, SourceSha256, CreatedAtUtc, PackageStatus, SourceMetadataJson
        FROM prep.InvoicePackage WHERE PackageId IN (SELECT PackageId FROM #SourcePackage)
        EXCEPT SELECT * FROM #SourcePackage
    )
        THROW 51416, 'An existing package differs or has progressed past staging. No data was overwritten.', 1;
    IF EXISTS (
        SELECT PackageId, InvoiceLineId, InvoiceID, LineNumber, Description, PartNumber, Quantity,
            UnitCost, LineAmount, PoLineNumber, PoDescription, PoTaskCode, AfeProjectId, SiteId, SourceLineJson
        FROM prep.InvoiceLine WHERE PackageId IN (SELECT PackageId FROM #SourcePackage)
        EXCEPT SELECT * FROM #SourceLine
    )
        THROW 51417, 'Existing invoice lines differ from source facts. No data was overwritten.', 1;

    INSERT INTO prep.Invoice
        (InvoiceID, InvoiceNumber, InvoiceDate, VendorID, VendorName, InvoiceCurrency,
         InvoiceTotal, PONumber, CountryRegion, SourceSystem, NuvoloWorkOrderNo,
         HasLineItems, RunID, LoadedAtUtc)
    SELECT *, SYSUTCDATETIME() FROM #SourceInvoice AS source
    WHERE NOT EXISTS (SELECT 1 FROM prep.Invoice WHERE InvoiceID = source.InvoiceID);

    INSERT INTO prep.InvoicePackage
        (PackageId, SchemaVersion, RunId, InvoiceId, InvoiceNumber, InvoiceDate,
         VendorId, VendorName, Currency, InvoiceTotal, PoNumber, CountryRegion, SourceSystem,
         BusinessUnit, ProjectStatus, ProjectType, BundlingInScope, MissingPo, MissingProject,
         MissingSite, SourcePackageName, SourceSha256, CreatedAtUtc, PackageStatus, SourceMetadataJson)
    SELECT * FROM #SourcePackage AS source
    WHERE NOT EXISTS (SELECT 1 FROM prep.InvoicePackage WHERE PackageId = source.PackageId);

    INSERT INTO prep.InvoiceLine
        (PackageId, InvoiceLineId, InvoiceID, LineNumber, Description, PartNumber, Quantity,
         UnitCost, LineAmount, PoLineNumber, PoDescription, PoTaskCode, AfeProjectId, SiteId, SourceLineJson)
    SELECT * FROM #SourceLine AS source
    WHERE NOT EXISTS (SELECT 1 FROM prep.InvoiceLine
        WHERE PackageId = source.PackageId AND InvoiceLineId = source.InvoiceLineId);

    IF EXISTS (
        SELECT * FROM #SourceInvoice
        EXCEPT
        SELECT InvoiceID, InvoiceNumber, InvoiceDate, VendorID, VendorName, InvoiceCurrency,
            InvoiceTotal, PONumber, CountryRegion, SourceSystem, NuvoloWorkOrderNo, HasLineItems, RunID
        FROM prep.Invoice
    ) OR EXISTS (
        SELECT * FROM #SourcePackage
        EXCEPT
        SELECT PackageId, SchemaVersion, RunId, InvoiceId, InvoiceNumber, InvoiceDate,
            VendorId, VendorName, Currency, InvoiceTotal, PoNumber, CountryRegion, SourceSystem,
            BusinessUnit, ProjectStatus, ProjectType, BundlingInScope, MissingPo, MissingProject,
            MissingSite, SourcePackageName, SourceSha256, CreatedAtUtc, PackageStatus, SourceMetadataJson
        FROM prep.InvoicePackage
    ) OR EXISTS (
        SELECT * FROM #SourceLine
        EXCEPT
        SELECT PackageId, InvoiceLineId, InvoiceID, LineNumber, Description, PartNumber, Quantity,
            UnitCost, LineAmount, PoLineNumber, PoDescription, PoTaskCode, AfeProjectId, SiteId, SourceLineJson
        FROM prep.InvoiceLine
    )
        THROW 51421, 'Persisted source values do not match the extraction. Load rolled back.', 1;

    IF (SELECT COUNT_BIG(*) FROM prep.Invoice WHERE InvoiceID IN (SELECT InvoiceID FROM #SourceInvoice)) <> 10
        OR (SELECT COUNT_BIG(*) FROM prep.InvoicePackage WHERE PackageId IN (SELECT PackageId FROM #SourcePackage)) <> 10
        OR (SELECT COUNT_BIG(*) FROM prep.InvoiceLine WHERE PackageId IN (SELECT PackageId FROM #SourcePackage)) <> 30
        THROW 51418, 'Source load row-count reconciliation failed. Load rolled back.', 1;
    IF EXISTS (SELECT * FROM #TaskMasterBeforeLoad EXCEPT SELECT * FROM ref.TaskMaster)
        OR EXISTS (SELECT * FROM ref.TaskMaster EXCEPT SELECT * FROM #TaskMasterBeforeLoad)
        THROW 51419, 'TaskMaster preservation check failed. Load rolled back.', 1;

    COMMIT TRANSACTION;
    SELECT
        'SOURCE_INVOICES_LOADED' AS LoadStatus,
        invoice.InvoiceID, invoice.InvoiceNumber, invoice.InvoiceDate,
        invoice.VendorID, invoice.VendorName, invoice.InvoiceCurrency, invoice.InvoiceTotal,
        package.PackageId, package.PackageStatus, package.SourcePackageName,
        (SELECT COUNT_BIG(*) FROM prep.InvoiceLine AS line WHERE line.PackageId = package.PackageId) AS LineCount,
        (SELECT COUNT_BIG(*) FROM prep.InvoiceLine AS line WHERE line.PackageId = package.PackageId
            AND line.Quantity IS NULL) AS MissingQuantityLines,
        (SELECT COUNT_BIG(*) FROM prep.InvoiceLine AS line WHERE line.PackageId = package.PackageId
            AND line.UnitCost IS NULL) AS MissingUnitCostLines
    FROM prep.Invoice AS invoice
    JOIN prep.InvoicePackage AS package ON package.InvoiceId = invoice.InvoiceID
    WHERE package.PackageId IN (SELECT PackageId FROM #SourcePackage)
    ORDER BY invoice.SourceSystem, invoice.InvoiceID;

    DROP TABLE #TaskMasterBeforeLoad;
    DROP TABLE #SourceInvoice;
    DROP TABLE #SourcePackage;
    DROP TABLE #SourceLine;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;
    DROP TABLE IF EXISTS #TaskMasterBeforeLoad;
    DROP TABLE IF EXISTS #SourceInvoice;
    DROP TABLE IF EXISTS #SourcePackage;
    DROP TABLE IF EXISTS #SourceLine;
    THROW;
END CATCH;
